"""Helpers for naming and composing load-case terms."""

from __future__ import annotations

from ..models import pattern_name


def mech_case_name(direction: str) -> str:
    """Return the mechanical analysis-case name for a direction such as ``+X``."""
    return f"W_Mech_{direction}"


def case_for(family: str, direction: str) -> str:
    """Resolve a load family and direction to the case name generated by ``patterns``."""
    return mech_case_name(direction) if family == "Mech" else pattern_name(family, direction)


def directional_sum_terms(direction: str, factor: float = 1.0) -> list[tuple[str, float]]:
    """Terms for one directional wind case: wall, parapet, penthouse, and mechanical."""
    return [(case_for(family, direction), factor) for family in ("Wall", "Parapet", "PH", "Mech")]


def eccentricity_term(direction: str, factor: float) -> tuple[str, float]:
    """Return the eccentric load-case term for a direction and signed factor."""
    return pattern_name("Ecc", direction), factor
